    78	// enchanted item is reimbursed at half; all other damage in full.
    79	// The dragon-material clause is subsumed by that default: it reimburses in
    80	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
    81	// it never changes a payout and needs no branch of its own.
    82	// An item the policy does not list has no clause and is reimbursed in full --
    83	// rejecting such a damage entry is a separate, not yet implemented rule.
    84	function reimbursementRateFor(item: Item): number {
    85	  return isHighlyEnchanted(item)
    86	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    87	    : FULL_REIMBURSEMENT_RATE;
    88	}
    89	
    90	// The MHPCO settles each damage event separately: it reimburses the damage
    91	// under the applicable clause, then withholds its deductible once per event.
    92	// A damage event reports what was lost, so its amount cannot be negative.
    93	function reportedAmountOf(damage: Damage): number {
