   102	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
   103	  const rate = reimbursementRateFor(
   104	    firstInsuredItemCoveringDamage(policy, damage),
   105	  );
   106	  return reportedAmountOf(damage) * rate - DEDUCTIBLE_PER_DAMAGE;
   107	}
   108	
   109	// What the MHPCO owes for the whole incident before rounding: every damage
   110	// event settled under its clause, reduced to what the policy's lifetime cap
   111	// still allows.
   112	function cappedSettlement(policy: Policy, incident: Incident): number {
   113	  const settled = incident.damages
   114	    .map((damage) => settlementForDamageEvent(policy, damage))
   115	    .reduce((sum, amount) => sum + amount, 0);
   116	  return Math.min(settled, policy.remainingCap);
   117	}
   118	
   119	export function claim(policy: Policy, incident: Incident): ClaimResult {
   120	  // A payout is owed by the MHPCO, so its fraction is rounded down. Only this
   121	  // final amount is rounded; the settlement above stays fractional. Rounding
   122	  // last is safe for a capped claim too: the cap is always a whole number of
   123	  // G, so rounding a capped settlement changes nothing.
   124	  const payout = amountOwedByMhpco(cappedSettlement(policy, incident));
   125	  const remainingCap = policy.remainingCap - payout;
   126	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
