    35	// The MHPCO settles a scenario's steps in order for a single customer: each
    36	// quote opens a policy the later claims draw on, and every quote after the
    37	// customer's first is a follow-up contract.
    38	export function runScenario(scenario: Scenario): StepResult[] {
    39	  const policies = new Map<number, Policy>();
    40	  let previousContracts = 0;
    41	  return scenario.steps.map((step, stepIndex) => {
    42	    if (step.op === "quote") {
    43	      const premium = quote(scenario.customer, step.items, previousContracts);
    44	      previousContracts += 1;
    45	      policies.set(stepIndex, openPolicy(step.items));
    46	      return { premium };
    47	    }
    48	    const result = claim(policyFor(policies, step.policy), step.incident);
    49	    policies.set(step.policy, result.policy);
    50	    return { payout: result.payout, remainingCap: result.remainingCap };
